"""Shared normalization pass.

Adapters emit LineItems whose money fields are integer cents. This pass
enforces that invariant before pricing:

- currency must be settleable (FX hook below for future currencies)
- quantity and unit_cents must be ints (adapters returning bools or
  Decimals is a bug this pass turns into a loud failure)
- zero-quantity lines are dropped
- descriptions are trimmed to the render width

Note on units: cents are the internal representation end to end. The
conversion to display dollars happens once, downstream, at render time
(billing.currency.cents_to_dollars). Nothing in this pass rescales an
amount; adapters hand over cents and cents leave here untouched.
"""

from dataclasses import replace

from . import currency
from .errors import BillingError

#: Settlement conversion table. Only USD today; rates are expressed as
#: minor-units-per-minor-unit so adding a currency does not change the
#: integer-cents invariant.
_FX_TO_USD = {
    "USD": 1,
}

#: Longest description the renderer will show.
_MAX_DESCRIPTION = 60


def normalize_items(items):
    """Normalize a list of LineItems, dropping empty lines."""
    normalized = []
    for item in items:
        if item.quantity == 0:
            continue
        normalized.append(_normalize(item))
    return normalized


def _normalize(item):
    if item.currency not in _FX_TO_USD:
        raise BillingError(
            f"cannot settle {item.currency!r} for customer {item.customer_id}"
        )
    _require_int("quantity", item.quantity)
    _require_int("unit_cents", item.unit_cents)

    fx = _FX_TO_USD[item.currency]
    unit_cents = item.unit_cents * fx

    description = " ".join(item.description.split())
    if len(description) > _MAX_DESCRIPTION:
        description = description[: _MAX_DESCRIPTION - 1] + "…"

    if unit_cents == item.unit_cents and description == item.description:
        return item
    return replace(item, unit_cents=unit_cents, description=description)


def _require_int(name, value):
    """Reject anything that is not a genuine int (bool included)."""
    if not isinstance(value, int) or isinstance(value, bool):
        raise BillingError(
            f"{name} must be int cents, got {type(value).__name__}: {value!r}"
        )
"""Billing periods and period bucketing.

A Period is a closed date interval with a display label. The report
runs one quarter at a time; items dated outside the period are simply
not billed in this run (they belong to another invoice).
"""

from dataclasses import dataclass
from datetime import date as Date, timedelta

_QUARTER_START_MONTH = {1: 1, 2: 4, 3: 7, 4: 10}


@dataclass(frozen=True)
class Period:
    """A closed billing interval: start and end are both billable days."""

    label: str
    start: Date
    end: Date

    def __post_init__(self):
        if self.end < self.start:
            raise ValueError(f"period {self.label}: end before start")

    def contains(self, day):
        """True when *day* falls inside the period, inclusive."""
        return self.start <= day <= self.end

    @property
    def days(self):
        """Number of billable days in the period."""
        return (self.end - self.start).days + 1


def quarter(year, q):
    """Build the Period for calendar quarter *q* of *year*."""
    if q not in _QUARTER_START_MONTH:
        raise ValueError(f"quarter must be 1-4, got {q}")
    start = Date(year, _QUARTER_START_MONTH[q], 1)
    if q == 4:
        next_start = Date(year + 1, 1, 1)
    else:
        next_start = Date(year, _QUARTER_START_MONTH[q + 1], 1)
    end = next_start - timedelta(days=1)
    return Period(label=f"{year} Q{q}", start=start, end=end)


def month(year, m):
    """Build the Period for one calendar month (used by ad-hoc reruns)."""
    start = Date(year, m, 1)
    if m == 12:
        next_start = Date(year + 1, 1, 1)
    else:
        next_start = Date(year, m + 1, 1)
    return Period(label=f"{year}-{m:02d}", start=start, end=next_start - timedelta(days=1))


def filter_items(items, period):
    """Keep only the items whose service date falls inside *period*."""
    return [item for item in items if period.contains(item.service_date)]


def split_by_month(items):
    """Bucket items by (year, month) of service date, for detail views."""
    buckets = {}
    for item in items:
        key = (item.service_date.year, item.service_date.month)
        buckets.setdefault(key, []).append(item)
    return dict(sorted(buckets.items()))
"""Aggregation: fold the flat item stream into per-customer rollups.

Grouping is by customer, then by (SKU, unit price) inside the customer.
The result preserves enough detail to render an invoice body while
giving the pricing stages a single subtotal to work from.
"""

from .models import CustomerAggregate


def aggregate_items(items):
    """Group *items* into {customer_id: CustomerAggregate}.

    Aggregate lines within each customer are sorted by SKU (then unit
    price) so invoice bodies render deterministically regardless of
    source file ordering.
    """
    by_customer = {}
    for item in items:
        agg = by_customer.get(item.customer_id)
        if agg is None:
            agg = CustomerAggregate(customer_id=item.customer_id)
            by_customer[item.customer_id] = agg
        agg.add(item)

    for agg in by_customer.values():
        agg.lines.sort(key=lambda line: (line.sku, line.unit_cents))
    return by_customer


def total_activity_cents(aggregates):
    """Sum of every customer's subtotal — the period's gross activity."""
    return sum(agg.subtotal_cents for agg in aggregates.values())


def line_count(aggregates):
    """Total number of aggregate lines across all customers."""
    return sum(len(agg.lines) for agg in aggregates.values())

